mapper.select:
SELECT m.symbol AS symbol, p.id AS pool_id, p.name AS name, p.pool_type AS pool_type FROM stock_pool_members m JOIN stock_pools p ON p.id = m.pool_id WHERE m.symbol IN
#{symbol}
AND (p.is_archived IS NULL OR p.is_archived = false) ORDER BY m.symbol, p.id

SELECT m.symbol AS symbol, c.id AS concept_id, c.name AS name, COALESCE(c.source, 'ths') AS source, COALESCE(c.concept_type, 'other') AS concept_type FROM fundamental_concept_member m JOIN fundamental_concept c ON c.id = m.concept_id WHERE m.symbol IN
#{symbol}
ORDER BY m.symbol, c.id

WITH kline AS ( SELECT symbol, COUNT(*) AS record_count, MIN(date)::text AS kline_start, MAX(date)::text AS kline_end FROM tech_kline_daily WHERE symbol IN
#{symbol}
GROUP BY symbol ), latest_basic AS ( SELECT d.symbol, d.close, d.total_mv, d.pe_ttm FROM fundamental_daily_basic d JOIN (SELECT symbol, MAX(trade_date) AS md FROM fundamental_daily_basic WHERE symbol IN
#{symbol}
GROUP BY symbol) t ON t.symbol = d.symbol AND t.md = d.trade_date ), latest_report AS ( SELECT r.symbol, r.n_income, r.revenue FROM fundamental_report r JOIN (SELECT symbol, MAX(end_date) AS md FROM fundamental_report WHERE report_type = '1' AND symbol IN
#{symbol}
GROUP BY symbol) t ON t.symbol = r.symbol AND t.md = r.end_date WHERE r.report_type = '1' ) SELECT k.symbol AS symbol, COALESCE(k.record_count, 0) AS record_count, k.kline_start AS kline_start, k.kline_end AS kline_end, b.close AS latest_close, b.total_mv AS total_mv, b.pe_ttm AS pe_ttm, CASE WHEN r.revenue IS NULL OR r.revenue = 0 THEN NULL ELSE ROUND((r.n_income / r.revenue) * 100, 2) END AS profit_margin FROM kline k LEFT JOIN latest_basic b ON b.symbol = k.symbol LEFT JOIN latest_report r ON r.symbol = k.symbol
